import { z } from 'zod';
import {
  CosmosCursorSchema,
  CosmosIdSchema,
  CosmosPageSchema,
} from '../../types/cosmos';
import type { BoardPage } from './boardPage';

const MAX_COLLECTIONS = 10_000;
const IdsSchema = z.array(CosmosIdSchema).max(MAX_COLLECTIONS);
const CursorSchema = z.object({
  root: z.object({ id: CosmosIdSchema, title: z.string() }),
  current: z.object({
    id: CosmosIdSchema,
    cursor: CosmosCursorSchema.optional(),
    total: z.number().int().nonnegative().optional(),
    children: IdsSchema.optional(),
  }),
  pending: IdsSchema,
  visited: IdsSchema,
});
export const cosmosRequest = (cursor: string | null) => {
  if (!cursor) return {};
  const { current } = CursorSchema.parse(JSON.parse(cursor));
  return { collectionId: current.id, cursor: current.cursor };
};
export const limitCosmosTraversal = (
  cursor: string | null,
  collectionIds: ReadonlySet<string>,
): string | null => {
  if (!cursor) return null;
  const state = CursorSchema.parse(JSON.parse(cursor));
  const pending = state.pending.filter((id) => collectionIds.has(id));
  if (collectionIds.has(state.current.id))
    return JSON.stringify({ ...state, pending });
  const id = pending.shift();
  return id ? JSON.stringify({ ...state, current: { id }, pending }) : null;
};
export const cosmosPage = (
  input: unknown,
  cursor: string | null,
): BoardPage => {
  const page = CosmosPageSchema.parse(input);
  const previous = cursor ? CursorSchema.parse(JSON.parse(cursor)) : null;
  const state = previous ?? {
    root: { id: page.collection.id, title: page.collection.title },
    current: { id: page.collection.id },
    pending: [],
    visited: [],
  };
  if (state.current.id !== page.collection.id)
    throw new Error('Cosmos collection identity changed');
  if (state.current.total !== undefined && state.current.total !== page.total)
    throw new Error('Cosmos collection count changed; refresh the source');
  if (
    state.current.children &&
    JSON.stringify(state.current.children) !==
      JSON.stringify(page.collection.children)
  )
    throw new Error('Cosmos subcollections changed; refresh the source');
  if (page.nextCursor && !page.elements.length)
    throw new Error('Cosmos returned an empty page with more results');
  if (
    new Set(page.elements.map((item) => item.id)).size !== page.elements.length
  )
    throw new Error('Cosmos returned duplicate elements');
  if (!state.visited.includes(page.collection.id)) {
    state.visited.push(page.collection.id);
    for (const child of page.collection.children)
      if (!state.visited.includes(child) && !state.pending.includes(child))
        state.pending.push(child);
  }
  const collection = {
    id: page.collection.id,
    total: page.total,
    isComplete: page.nextCursor === null,
  };
  let next: z.infer<typeof CursorSchema> | null = null;
  if (page.nextCursor) {
    next = {
      ...state,
      current: {
        id: page.collection.id,
        cursor: page.nextCursor,
        total: page.total,
        children: page.collection.children,
      },
    };
  } else {
    const id = state.pending.shift();
    if (id) next = { ...state, current: { id } };
  }
  return {
    remoteId: state.root.id,
    title: state.root.title,
    cursor: next ? JSON.stringify(CursorSchema.parse(next)) : null,
    isComplete: next === null,
    collection,
    references: page.elements.map((item) => ({
      provider: 'cosmos',
      remoteId: item.id,
      title: item.title,
      text: [
        item.text,
        item.author ? `Author: ${item.author}` : '',
        item.owner ? `Saved by: ${item.owner}` : '',
        item.sourceUrl ? `Source: ${item.sourceUrl}` : '',
      ]
        .filter(Boolean)
        .join('\n'),
      url: item.url,
      media: [],
      remoteImages: item.images.map((image) => image.url),
      remoteImageRepresentations: item.images.map(
        (image) => image.representation,
      ),
      ...(item.unsupportedReason
        ? { unsupportedReason: item.unsupportedReason }
        : {}),
    })),
  };
};
